/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect, useContext } from 'react'
import { Row, Col, Button, Select, Input, Checkbox, Divider, Icon } from 'antd'
import { get } from 'lodash'
import TableField from '../TableData'
import { store } from '../../context/attributeContext'
import StyledContainer from './index.style'
import { objectTypeHandler } from './buttonHandlers'
import { inputFieldsHandler } from './inputHandler'
import AddAttributeModal from './NewAttributeAddModal'

const { Option } = Select
export default function PayloadField ({ provider, providerList, stateData, type = 'regular' }) {
  const { state, dispatch } = useContext(store)
  const [modalVisible, setModalVisible] = useState(false)
  const buttonType = get(stateData, 'buttonType')
  const fallbackType = get(stateData, 'fallback_type')
  const [providerListState, setProviderList] = useState([])
  const [attributeListState, setAttributeList] = useState([])
  const currentStateId = get(stateData, 'id')
  const fallbackTypeList = ["static", "derived"]
  const statusTypeList = ["active", "not_active"]

  useEffect(() => {
    const step2Data = get(state, 'attributesList', [])
    setAttributeList(step2Data)
  }, [state])

  useEffect(() => {
    if (buttonType) {
      const buttonTypeProviderList = providerList.filter(item => {
        if (buttonType === 'object') {
          return item.type === 'object'
        } else if (buttonType === 'regular') {
          return item.type !== 'object'
        } else {
          return false
        }
      })
      setProviderList(buttonTypeProviderList)
    }
  }, [providerList])

  const buttonHandler = (type) => {
    if (type === 'regular') {
      const newProvidrList = providerList.filter(item => item.type !== 'object')
      setProviderList(newProvidrList)
    } else {
      const newProvidrList = providerList.filter(item => item.type === 'object')
      setProviderList(newProvidrList)
    }
    const originalData = objectTypeHandler(type, state, currentStateId)
    dispatch({
      type: 'update-data',
      payload: originalData
    })
  }
  const inputHandler = (type, value, providerListState) => {
    const data = inputFieldsHandler(type, currentStateId, value, state, providerListState)
    dispatch({
      type: 'update-data',
      payload: data
    })
  }
  const modalVisibleHandler = () => {
    setModalVisible(false)
  }
  return (
    <StyledContainer type={type}>
      <AddAttributeModal
        visible={modalVisible}
        functionName={get(state, 'functionName')}
        provider={provider}
        modalHandler={modalVisibleHandler}
      />
      <Row type='flex' justify='center'>
        <Col span={8}>
          <div className='button__section'>
            <Button type={buttonType === 'regular' ? 'primary' : 'default'} onClick={() => buttonHandler('regular')}>Regular</Button>
            <Button type={buttonType === 'object' ? 'primary' : 'default'} onClick={() => buttonHandler('object')}>Object</Button>
          </div>
        </Col>
        {
          buttonType === 'regular' &&
            <Col span={20}>
              <Row type='flex' justify='space-between' align='middle'>
                <Col className='field__section' span={10}>
                  <label>Field key</label><br />
                  <Select
                    className='field__section_select'
                    showSearch
                    dropdownStyle={{ fontSize: 12 }}
                    value={get(stateData, 'provider_attribute_id')}
                    disabled={get(stateData, 'fieldType') === 'disabled'}
                    onChange={(e) => inputHandler('provider_attribute_id', e, providerListState)}
                    filterOption={
                      (input, option) =>
                        option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                    }
                    dropdownRender={menu => (
                      <div>
                        {menu}
                        <Divider style={{ margin: '4px 0' }} />
                        <div
                          style={{ padding: '4px 8px', cursor: 'pointer' }}
                          onMouseDown={e => e.preventDefault()}
                          onClick={() => setModalVisible(true)}
                        >
                          <Icon type='plus' /> Add item
                        </div>
                      </div>
                    )}
                  >
                    {providerListState.map((item, index) => (
                      <Option
                        key={index}
                        value={item.id}
                        searchValue={`${item.name} ${item.code}`}
                      >
                        {item.name} <b>({item.code})</b>
                      </Option>
                    ))}
                  </Select>
                </Col>
                <Col className='field__section' span={10}>
                  <label>Data Mapping</label><br />
                  <Select
                    showSearch
                    allowClear
                    dropdownStyle={{ fontSize: 12 }}
                    className='field__section_select'
                    value={get(stateData, 'product_attribute_id')}
                    onChange={(e) => inputHandler('product_attribute_id', e)}
                    filterOption={
                      (input, option) =>
                        option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                    }
                  >
                    {attributeListState.map((item, index) => (
                      <Option
                        key={index}
                        value={item.id}
                        searchValue={`${item.name} ${item.attribute_type}`}
                      >
                        {item.name} <b>({item.attribute_type})</b>
                      </Option>
                    ))}
                  </Select>
                </Col>
                <Col className='field__section' span={10}>
                  <label>Prefix</label><br />
                  <Input
                    value={get(stateData, 'prefix')}
                    onChange={(e) => inputHandler('prefix', e.target.value)}
                  />
                </Col>
                <Col className='field__section' span={10}>
                  <label>Suffix</label><br />
                  <Input
                    value={get(stateData, 'suffix')}
                    onChange={(e) => inputHandler('suffix', e.target.value)}
                  />
                </Col>
                <Col className='field__section' span={10}>
                  <label>FallBack Type</label><br />
                  <Select
                    showSearch
                    allowClear
                    dropdownStyle={{ fontSize: 12 }}
                    className='field__section_select'
                    value={get(stateData, 'fallback_type')}
                    onChange={(e) => inputHandler('fallback_type', e)}
                    filterOption={
                      (input, option) =>
                        option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                    }
                  >
                    {fallbackTypeList.map((item, index) => (
                      <Option
                        key={index}
                        value={item}
                        searchValue={`${item}`}
                        >
                        {item}
                        </Option>
                    ))}
                  </Select>
                </Col>
                <Col className='field__section' span={10}>
                {fallbackType == "static" && <div>
                    <label>Fallback Static Value</label><br />
                    <Input
                        value={get(stateData, 'fallback_static_value')}
                        onChange={(e) => inputHandler('fallback_static_value', e.target.value)}
                    />
                </div>}
                {fallbackType == "derived" && <div>
                    <label>FallBack Data Mapping</label><br />
                    <Select
                        showSearch
                        allowClear
                        dropdownStyle={{ fontSize: 12 }}
                        className='field__section_select'
                        value={get(stateData, 'fallback_product_attribute_id')}
                        onChange={(e) => inputHandler('fallback_product_attribute_id', e)}
                        filterOption={
                        (input, option) =>
                            option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                        }
                    >
                        {attributeListState.map((item, index) => (
                        <Option
                            key={index}
                            value={item.id}
                            searchValue={`${item.name} ${item.attribute_type}`}
                        >
                            {item.name} <b>({item.attribute_type})</b>
                        </Option>
                        ))}
                    </Select>
                </div>}
                </Col>
                <Col className='field__section' span={10}>
                  <label>Formatting</label><br />
                  <Input
                    value={get(stateData, 'formatting')}
                    onChange={(e) => inputHandler('formatting', e.target.value)}
                  />
                </Col>
                <Col className='field__section' span={10}>
                  <div className='checkbox__section'>
                    <Checkbox
                      checked={get(stateData, 'convert_value_to_string')}
                      onChange={(e) => inputHandler('convert_value_to_string', e.target.checked)}
                    >convert to string in the payload
                    </Checkbox>
                    <Checkbox
                      checked={get(stateData, 'convert_value_to_numeric')}
                      onChange={(e) => inputHandler('convert_value_to_numeric', e.target.checked)}
                    >convert to numeric in the payload
                    </Checkbox>
                    <Checkbox
                      checked={get(stateData, 'is_array')}
                      onChange={(e) => inputHandler('is_array', e.target.checked)}
                    >value in array
                    </Checkbox>
                    <label>Status</label>
                    <Select
                        dropdownStyle={{ fontSize: 12 }}
                        className='field__section_select'
                        value={get(stateData, 'status')}
                        onChange={(e) => inputHandler('status', e)}>
                        {statusTypeList.map((item, index) => (
                        <Option
                            key={index}
                            value={item}
                            searchValue={`${item}`}
                            >
                            {item}
                            </Option>
                        ))}
                    </Select>
                  </div>
                </Col>
              </Row>
            </Col>
        }
        {
          buttonType === 'object' &&
            <Col span={20}>
              <Row type='flex' justify='center'>
                <Col className='field__section' span={10}>
                  <label>Field key</label><br />
                  <Select
                    showSearch
                    value={get(stateData, 'provider_attribute_id')}
                    disabled={get(stateData, 'fieldType') === 'disabled'}
                    onChange={(e) => inputHandler('provider_attribute_id', e)}
                    style={{ width: 210 }}
                    dropdownRender={menu => (
                      <div>
                        {menu}
                        <Divider style={{ margin: '4px 0' }} />
                        <div
                          style={{ padding: '4px 8px', cursor: 'pointer' }}
                          onMouseDown={e => e.preventDefault()}
                          onClick={() => setModalVisible(true)}
                        >
                          <Icon type='plus' /> Add item
                        </div>
                      </div>
                    )}
                  >
                    {providerListState.map((item, index) => (<Option key={index} value={item.id}>{item.name}</Option>))}
                  </Select>
                </Col>
              </Row>
              <Row type='flex' justify='center'>
                <Col className='field__section' span={10}>
                  <div className='checkbox__section'>
                    <Checkbox
                      checked={get(stateData, 'is_array')}
                      onChange={(e) => inputHandler('is_array', e.target.checked)}
                    >value in array
                    </Checkbox>
                  </div>
                </Col>
              </Row>
            </Col>
        }
        {
          stateData.tableShow &&
            <Col className='attributes__table' span={22}>
              <TableField
                type='modal'
                tableData={stateData.tableData}
                parentId={stateData.id}
                step2={attributeListState}
                provider={provider}
              />
            </Col>
        }
      </Row>
    </StyledContainer>
  )
}
