import { get, size } from 'lodash'
import { notification } from 'antd'

export function inputFieldsHandler (type, id, value, originalState, providerListState = []) {
  const contextData = get(originalState, 'data', [])
  let newFormedData = [...contextData]
  switch (type) {
    case 'is_array':
    case 'prefix':
    case 'suffix':
    case 'formatting':
    case 'product_attribute_id':
    case 'convert_value_to_string':
    case 'fallback_type':
    case 'fallback_static_value':
    case 'status':
    case 'convert_value_to_numeric':
    case 'fallback_product_attribute_id':
      newFormedData = newFormedData.map((item) => {
        if (item.id === id) {
          return {
            ...item,
            [type]: value
          }
        } else {
          return item
        }
      })
      break
    case 'provider_attribute_id': {
      const initialIdPresentCheck = newFormedData.find((item) => item.provider_attribute_id === id) || {}
      if (size(initialIdPresentCheck) > 0) {
        notification.error({
          message: "Same attribute can't exists on same level"
        })
      } else {
        newFormedData = newFormedData.map((item) => {
          if (item.id === id) {
            return {
              ...item,
              datatype: get(providerListState.find(item => item.id === value), 'type'),
              [type]: value
            }
          } else {
            return item
          }
        })
        if (id === 1) {
          const firstItem = newFormedData[0]
          if (get(firstItem, 'buttonType') === 'object') {
            newFormedData = [...newFormedData, {
              id: 2,
              datatype: '',
              fieldType: 'enabled',
              provider_attribute_id: null,
              buttonType: 'regular',
              parent_id: value,
              product_attribute_id: null,
              fallback_product_attribute_id: null,
              fallback_type: null,
              status: 'active',
              convert_value_to_numeric: false,
              fallback_static_value: '',
              is_array: false,
              prefix: '',
              suffix: '',
              convert_value_to_string: false,
              formatting: '',
              showAddButton: true,
              showDeleteButton: true,
              tableShow: false,
              tableData: []
            }]
          }
        }
      }
    }
      break
    default: return newFormedData
  }
  return newFormedData
}

export function addItemHandler (oldData) {
  oldData = oldData.map((item) => {
    return {
      ...item,
      showDeleteButton: true
    }
  })
  const lastItem = oldData[oldData.length - 1]
  const lastitemindex = get(lastItem, 'id')
  return [...oldData, {
    id: lastitemindex + 1,
    fieldType: 'enabled',
    provider_attribute_id: null,
    buttonType: 'regular',
    parent_id: get(lastItem, 'parent_id'),
    product_attribute_id: null,
    fallback_product_attribute_id: null,
    fallback_type: null,
    status: 'active',
    convert_value_to_numeric: false,
    fallback_static_value: '',
    is_array: false,
    prefix: '',
    suffix: '',
    convert_value_to_string: false,
    formatting: '',
    showAddButton: true,
    showDeleteButton: true,
    tableShow: false,
    tableData: []
  }]
}

export function deleteItemHandler (id, oldData) {
  let newData = oldData.filter((item) => item.id !== id)
  newData = newData.map((item) => {
    return {
      ...item,
      showDeleteButton: item.fieldType !== 'disabled'
    }
  })
  if (newData.length === 1) {
    newData = newData.map((item) => {
      return {
        ...item,
        showDeleteButton: false
      }
    })
  }
  return newData
}
