/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect } from 'react'
import { get, size } from 'lodash'
import { Row, Col, Button } from 'antd'
import StepWrapper from '../components/Step'
import Step3Wrapper from '../index'
import Screen1 from './pages/Screen1'
import Screen2 from './pages/Screen2'
import { StyleContainer } from './index.style'
import { ProviderDetailContextProvider } from './context'
import { StateProvider } from './context/attributeContext'

export default function ProviderUiConfig ({ ...props }) {
  const [packageData, setPackageData] = useState({})
  const [productCode, setProductCode] = useState('')
  const [packageCode, setPacakgeCode] = useState('')
  const [step1Data, setStep1Data] = useState({})
  const [step2Data, setStep2Data] = useState([])
  const [screenType, setScreenType] = useState('screen1')
  const [newStep, setNewStep] = useState({
    provider: true,
    endorsement: false
  })
  const [provider, setProvider] = useState('')

  useEffect(() => {
    const { location } = props
    if (size(get(location, 'state', {})) > 0) {
      const formData = get(location, 'state.formData', {})
      const step1Data = get(location, 'state.formData.step1Data', '')
      setProductCode(get(step1Data, 'code'))
      setPacakgeCode(get(formData, 'packageData.code'))
      setPackageData(get(formData, 'packageData'))
      setStep1Data(get(formData, 'step1Data'))
      setStep2Data(get(formData, 'step2Data'))
      const endorsementSection = get(formData, 'packageData.has_endorsement_flow', false)
      setNewStep({
        ...newStep,
        endorsement: endorsementSection
      })
      const provider = get(formData, 'packageData.provider_code', '')
      setProvider(provider)
    }
    return () => {
      window.sessionStorage.clear('provider')
      window.sessionStorage.clear('attributeData')
    }
  }, [])

  const onBackHandler = () => {
    const { history } = props
    history.push({
      pathname: '/product-config/create-product/3/data-validation',
      state: {
        formName: 'providerPage',
        formData: {
          initialData: [],
          step1Data: step1Data,
          step2Data: step2Data,
          packageData: packageData
        }
      }
    })
  }
  const onChangeScreenHandler = (type) => {
    setScreenType(type)
  }
  const nextButtonHandler = () => {
    const { location, history } = props
    const formData = get(location, 'state.formData', {})
    if (get(newStep, 'endorsement')) {
      history.push({
        pathname: '/product-config/create-product/3/generic-endorsement-form',
        state: {
          formName: 'provider',
          formData: {
            step1Data: get(formData, 'step1Data'),
            step2Data: get(formData, 'step2Data'),
            packageData: get(location, 'state.formData.packageData', {})
          }
        }
      })
    } else {
      history.push({
        pathname: '/product-config/create-product/3',
        state: {
          formName: 'validation-table',
          formData: {
            step1Data: get(formData, 'step1Data'),
            step2Data: get(formData, 'step2Data'),
            packageData: get(location, 'state.formData.packageData', {})
          }
        }
      })
    }
  }
  return (
    <Step3Wrapper>
      <StepWrapper
        current={2}
        newSteps={newStep}
      >
        <ProviderDetailContextProvider>
          <StyleContainer type='add'>
            <Row type='flex' justify='center'>
              <Col span={22}>
                <StateProvider>
                  {
                    screenType === 'screen1'
                      ? <Screen1
                          type='add'
                          productCode={productCode}
                          packageCode={packageCode}
                          step2={step2Data}
                          provider={provider}
                          screenHandler={onChangeScreenHandler}
                        />
                      : <Screen2
                          type='add'
                          productCode={productCode}
                          packageCode={packageCode}
                          provider={provider}
                          step2={step2Data}
                          screenHandler={onChangeScreenHandler}
                        />
                  }
                </StateProvider>
              </Col>
              <Col className='col__section' span={8}>
                {
                  screenType === 'screen1' &&
                    <div className='btn__section'>
                      <Button onClick={onBackHandler}>Previous</Button>
                      <Button type='primary' onClick={nextButtonHandler}>Next</Button>
                    </div>
                }
              </Col>
            </Row>
          </StyleContainer>
        </ProviderDetailContextProvider>
      </StepWrapper>
    </Step3Wrapper>
  )
}
