/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect, useContext } from 'react'
import { Row, Col, Button, Icon, notification } from 'antd'
import { get } from 'lodash'
import { payloadFormation } from '../commanFunction/payloadFormation'
import { StyleContainer } from '../index.style'
import { store } from '../context/attributeContext'
import AttributeField from '../components/AttributeField'
import { useResetState, useApiVersionList, useAddProviderAttributes, useDataMappingValue } from '../hooks/useProviderDetails'
import { addItemHandler, deleteItemHandler } from '../components/AttributeField/inputHandler'
import { sessionTableMapper } from '../components/TableData/tableDataMapper'
import { useLoaderContextValue } from '../../../../../../../../globalContextProvider/LoaderContext'
import QuerySearchBuilder from '../../../../../../../../helpers/querySearchBuilder'

export default function Screen2 (props) {
  const { type = 'add', initialValue = [], productCode, packageCode, provider, screenHandler, history = {}, functionName = '' } = props
  const { state, dispatch } = useContext(store)
  const [atrributesData, setAttributesData] = useState([])
  const [{ dataMappingData, dataMappingStatus }, dataMappingRequest] = useDataMappingValue()
  const [{ apiVersionData }, apiVersionListRequest] = useApiVersionList()
  const [{ addProviderAttributesData, addProviderAttributesStatus }, attributeAddRequest] = useAddProviderAttributes()
  const [resetProviderDetailsState] = useResetState()
  const [{ ADD_PROVIDER_ATTRIBUTES_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    if (dataMappingStatus === 'success') {
      dispatch({
        type: 'attribute-list-update',
        payload: get(dataMappingData, 'data.details', [])
      })
      resetProviderDetailsState(['dataMappingStatus'])
    }
    if (addProviderAttributesStatus === 'success') {
      notification.success({
        message: get(addProviderAttributesData, 'message')
      })
      dispatch({
        type: 'update-data',
        payload: [state.normalMapping]
      })
      resetProviderDetailsState(['addProviderAttributesStatus', 'addProviderAttributesData'])
      const queryString = QuerySearchBuilder({ product_code: productCode })

      history.push({
        pathname: '/product-config/detail',
        search: queryString,
        state: {
          code: productCode,
          visible: '3',
          packageCode: packageCode
        }
      })
    }
    if (addProviderAttributesStatus !== 'success' && addProviderAttributesStatus !== undefined) {
      notification.error({
        message: get(addProviderAttributesData, 'message')
      })
      resetProviderDetailsState(['addProviderAttributesStatus', 'addProviderAttributesData'])
    }
  }, [addProviderAttributesData, dataMappingStatus])

  useEffect(() => {
    apiVersionListRequest({
      query: {
        provider_code: provider,
        function_name: type === 'edit' ? functionName : get(state, 'functionName', ''),
        attributeType: 'payload'
      }
    })
    dataMappingRequest({
      query: {
        productCode: productCode,
        type: 'creation,endorsement,internal'
      }
    })
  }, [])

  useEffect(() => {
    if (functionName) {
      dispatch({
        type: 'set-function-name',
        payload: functionName
      })
    }
  }, [functionName])

  useEffect(() => {
    const data = get(state, 'data', [])
    setAttributesData(data)
  }, [state])

  useEffect(() => {
    if (type === 'edit') {
      if (initialValue.length > 0) {
        dispatch({
          type: 'update-data',
          payload: initialValue
        })
        setAttributesData(initialValue)
      }
    }
  }, [initialValue])

  const cancelButtonHandler = () => {
    if (type === 'add') {
      dispatch({
        type: 'update-data',
        payload: [state.normalMapping]
      })
      setAttributesData([])
      screenHandler('screen1')
    } else {
      dispatch({
        type: 'update-data',
        payload: [state.normalMapping]
      })
      history.goBack()
    }
  }
  const buttonHandler = () => {
    const payload = payloadFormation(get(state, 'data', []))
    if (type === 'edit') {
      attributeAddRequest({
        query: {
          provider_code: provider,
          function_name: get(state, 'functionName'),
          product_code: productCode,
          package_code: packageCode
        },
        body: payload
      })
    } else {
      const oldData = JSON.parse(window.sessionStorage.getItem('attributeData')) || []
      const payload = sessionTableMapper(get(state, 'data', []))
      oldData.push(...payload)
      window.sessionStorage.setItem('attributeData', JSON.stringify(oldData))
      dispatch({
        type: 'update-collapse',
        payload: ['1', '2']
      })
      dispatch({
        type: 'update-data',
        payload: [state.normalMapping]
      })
      screenHandler('screen1')
    }
  }

  const addHandler = () => {
    const data = get(state, 'data', [])
    const modifiedData = addItemHandler(data)

    dispatch({
      type: 'update-data',
      payload: modifiedData
    })
  }

  const removeHandler = (id) => {
    const data = get(state, 'data', [])
    const modifiedData = deleteItemHandler(id, data)
    dispatch({
      type: 'update-data',
      payload: modifiedData
    })
  }
  return (
    <StyleContainer type='add'>
      <Row type='flex' justify='center'>
        <Col span={22}>
          <div className='attribute__container'>
            <Row type='flex' justify='center'>

              <Col className='attribute_heading_section' span={22}>
                {
                  type === 'add'
                    ? <p><b>Add new payload field</b></p>
                    : <p><b>Edit Provider field Attribute</b></p>
                }
              </Col>
              <Col span={22}>
                <Row type='flex' justify='center' align='middle'>
                  {
                    atrributesData.map((item, index) => {
                      return (
                        <Col span={24} className='attribute__section_box' key={index}>
                          <Row type='flex' justify='center' align='middle' gutter={30}>
                            <Col span={22}>
                              <AttributeField
                                type={type}
                                provider={provider}
                                providerList={get(apiVersionData, 'data.details.attributes', [])}
                                stateData={item}
                              />
                            </Col>
                            <Col span={2}>
                              <div className='icon-div'>
                                {
                                  item.showAddButton &&
                                    <Icon
                                      className='dynamic-add-button button-size'
                                      type='plus-circle'
                                      theme='filled'
                                      onClick={() => addHandler()}
                                    />
                                }
                                {
                                  item.showDeleteButton &&
                                    <Icon
                                      style={{ marginLeft: 5 }}
                                      className='dynamic-delete-button button-size'
                                      type='minus-circle'
                                      theme='filled'
                                      onClick={() => removeHandler(item.id)}
                                    />
                                }
                              </div>
                            </Col>
                          </Row>
                        </Col>
                      )
                    })
                  }
                </Row>
              </Col>
              <Col span={10}>
                <div className='btn__section'>
                  <Button type='default' onClick={cancelButtonHandler}>Cancel</Button>
                  {
                    type === 'edit'
                      ? <Button loading={ADD_PROVIDER_ATTRIBUTES_LOADER} type='primary' onClick={buttonHandler}>Submit</Button>
                      : <Button type='primary' onClick={buttonHandler}>Submit</Button>
                  }
                </div>
              </Col>
            </Row>
          </div>
        </Col>
      </Row>
    </StyleContainer>
  )
}
